INSERT INTO `projects` (`id`, `customer_id`, `service_id`, `title`, `description`, `requirements`, `budget`, `deadline`, `status`, `revision_expectations`, `selected_freelancer_id`) VALUES
(1, 1, 1, 'Enterprise AI Analytics Portal with Secure Escrow', 'Looking for an experienced engineer to build an end-to-end analytics dashboard with real-time data feeds, user role permissions, and transactional reporting.', '1. Modern React frontend with Tailwind/Bootstrap.\n2. Clean PHP 8.2 backend with PDO.\n3. MySQL database with indexes.\n4. Simulated Escrow workflow.', 2400.00, '2026-10-15', 'in_progress', '2 comprehensive rounds included.', 1),
(2, 1, 3, 'FinTech SaaS Mobile App Design System', 'Comprehensive UI/UX design in Figma including mobile application screens, dark/light theme component library, and interactive prototypes.', 'Deliverables must include Figma source files, tokens, and exportable SVG assets.', 1100.00, '2026-10-05', 'open', '3 design critique revisions.', NULL),
(3, 1, 4, 'Autonomous LLM Agent for Customer Support Triage', 'Develop an AI microservice that parses incoming user inquiries, classifies intent, and synthesizes accurate answers grounded in our documentation database.', 'Requires Python or Node microservice with structured JSON responses and error fallbacks.', 3200.00, '2026-11-01', 'open', '2 technical validation rounds.', NULL),
(4, 1, 10, 'SOC2 Cloud Security Audit & Pen-Test', 'Perform an external and internal penetration test on our cloud API endpoints and report vulnerabilities mapped to OWASP Top 10.', 'Full executive summary and remediations report required.', 1800.00, '2026-09-30', 'completed', 'Standard verification check.', 5)
INSERT INTO `proposals` (`id`, `project_id`, `freelancer_id`, `cover_letter`, `proposed_price`, `delivery_days`, `relevant_experience`, `status`, `ai_match_score`, `ai_match_reason`) VALUES
(1, 1, 1, 'Hello Sarah, I have built multiple enterprise SaaS portals with PHP 8.2 PDO and React. My Trust Score is 99.2 (Elite Tier), and I have completed 52 on-time projects with zero escrow disputes. I can deliver this system with clean architecture, prepared statements, and verified milestones.', 2400.00, 14, 'Built scalable FinTech dashboards with simulated escrow for Fortune 500 clients.', 'accepted', 97.80, 'Top skill alignment in React, PHP, MySQL with 100% on-time record and Elite trust tier.'),
(2, 1, 4, 'Hi Sarah, I would love to tackle the analytics portal. I specialize in full-stack React and PHP architecture. I can structure the MySQL schema cleanly.', 2100.00, 16, 'Developed 14 web applications using modern full-stack tools.', 'rejected', 82.40, 'Solid skill match in React and PHP; slightly lower historic volume of completed enterprise projects.'),
(3, 2, 3, 'Hi Sarah! As a Principal Product Designer specializing in FinTech, I have designed 20+ design systems with dark/light mode fidelity. I will provide a modular Figma design token library.', 1100.00, 9, 'Led design systems for two Series-A fintech startups.', 'pending', 94.50, 'High domain match in FinTech UX, verified portfolio tokens, and 95% on-time delivery rate.')
